INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (109, 'hotPreenchFinPorCr', 'Orcado+realizado por CR do gestor.', 'SQL', 'SELECT s.CR_ID,
       (SELECT COALESCE(SUM(VALOR),0) FROM ORCAMENTO WHERE CICLO_ID = s.CICLO_ID AND CR_ID = s.CR_ID) AS ORCADO,
       (SELECT COALESCE(SUM(VALOR),0) FROM REALIZADO_CONTABIL WHERE ANO = {{ano}} AND CR_ID = s.CR_ID) AS REALIZADO
